<?php
require_once __DIR__.'/../config/database.php';require_once __DIR__.'/../includes/auth.php';require_admin();if($_SERVER['REQUEST_METHOD']!=='POST')redirect('leads.php');verify_csrf();$ids=array_values(array_filter(array_map('intval',is_array($_POST['ids']??null)?$_POST['ids']:[]),fn($v)=>$v>0));if(!$ids){flash('error','No leads selected.');redirect('leads.php');}
try{$p=implode(',',array_fill(0,count($ids),'?'));$pdo->beginTransaction();$s=$pdo->prepare("SELECT file_path FROM documents WHERE lead_id IN ($p)");$s->execute($ids);foreach($s->fetchAll() as $f)if(is_file($f['file_path']))@unlink($f['file_path']);$pdo->prepare("DELETE mp FROM meeting_participants mp JOIN meetings m ON m.id=mp.meeting_id WHERE m.lead_id IN ($p)")->execute($ids);foreach(['meetings','lead_followups','documents','activities','negotiations','email_messages'] as $table)$pdo->prepare("DELETE FROM `$table` WHERE lead_id IN ($p)")->execute($ids);$pdo->prepare("DELETE FROM leads WHERE id IN ($p)")->execute($ids);$pdo->commit();flash('success',count($ids).' lead(s) deleted.');}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();flash('error','Could not delete selected leads.');}redirect('leads.php');
